-- pipeline/outlet-health
-- Every outlet with its last success and error, for the review area.
--
-- No parameters.
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

select "slug", "name", "enabled", "last_ok_at", "last_error", "consecutive_failures"
from "outlets"
order by "outlets"."name";
